import React, { useContext } from 'react';
import { CartContext } from '../../context/CartContext';
import { AuthContext } from '../../context/AuthContext';

function CartPage() {
    const { cart, dispatch } = useContext(CartContext);
    const { token } = useContext(AuthContext);

    const handleSubmit = async () => {
        for (const item of cart.items) {
            await fetch('http://localhost:5000/api/purchases', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify({
                    product: item._id,
                    supplier: item.supplier?._id,
                    quantity: item.quantity,
                    purchasePrice: item.currentPrice
                })
            });
        }
        dispatch({ type: 'CLEAR' });
        alert('Заказ оформлен');
    };

    return (
        <div className="cart">
            <h2>Корзина</h2>
            {cart.items.map(item => (
                <div key={item._id}>
                    {item.name} ×
                    <input
                        type="number"
                        value={item.quantity}
                        onChange={e =>
                            dispatch({
                                type: 'UPDATE',
                                payload: { _id: item._id, quantity: parseInt(e.target.value) }
                            })
                        }
                    />
                    <button onClick={() => dispatch({ type: 'REMOVE', payload: item._id })}>
                        Удалить
                    </button>
                </div>
            ))}
            <p>Итого: {cart.total} ₽</p>
            <button onClick={handleSubmit}>Оформить заказ</button>
        </div>
    );
}
